from datetime import datetime
from pathlib import Path
import base64
import py_compile
import shutil
import subprocess
import sys

FILES = {'app/services/teams_contact_workflow_service.py': '', 'app/services/teams_issue_workflow_service.py': ''}
stamp = datetime.now().strftime("%Y%m%d-%H%M%S")
backups = []
created = []


def rollback(message):
    print(f"[ERROR] {message}")
    for path in created:
        if path.exists():
            path.unlink()
    for path, backup in backups:
        shutil.copy2(backup, path)
    print("[ROLLBACK] Original state restored")
    sys.exit(1)

for file_name, encoded in FILES.items():
    path = Path(file_name)
    path.parent.mkdir(parents=True, exist_ok=True)
    if path.exists():
        backup = Path(str(path) + f".bak-teams-next-{stamp}")
        shutil.copy2(path, backup)
        backups.append((path, backup))
        print(f"[BACKUP] {backup}")
    else:
        created.append(path)
    path.write_bytes(base64.b64decode(encoded))

try:
    for file_name in FILES:
        py_compile.compile(file_name, doraise=True)
        print(f"[COMPILE OK] {file_name}")
except Exception as exc:
    rollback(f"Compile failed: {exc}")

checks = [
    "from app.services.teams_contact_workflow_service import collect_contact; assert callable(collect_contact)",
    "from app.services.teams_issue_workflow_service import collect_issue, build_ticket_subject; assert build_ticket_subject('Create a ticket for Outlook is broken')",
    "import app.main",
]
for check in checks:
    result = subprocess.run([sys.executable, "-c", check], capture_output=True, text=True)
    if result.returncode != 0:
        rollback(result.stderr or result.stdout)

print("[IMPORT OK] New services and app.main")
print("[SUCCESS] Created contact and issue workflow services")
print("Review with:")
for file_name in FILES:
    print(f"  git diff -- {file_name}")
